create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(trim(full_name)) >= 2), business_name text not null check (char_length(trim(business_name)) >= 2), email text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null check (char_length(trim(name)) > 0), sku text, category text, description text, cost_price numeric(12,2) not null default 0 check (cost_price >= 0), selling_price numeric(12,2) not null default 0 check (selling_price >= 0), low_stock_threshold integer not null default 0 check (low_stock_threshold >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, sku));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, movement_type text not null check (movement_type in ('IN','OUT')), quantity integer not null check (quantity > 0), unit_price numeric(12,2) check (unit_price is null or unit_price >= 0), reference text, note text, created_at timestamptz not null default now());
create table public.sales (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, quantity integer not null check (quantity > 0), unit_price numeric(12,2) not null check (unit_price >= 0), total numeric(12,2) not null check (total >= 0), customer text, created_at timestamptz not null default now());
create index products_user_id_idx on public.products(user_id); create index stock_movements_user_product_idx on public.stock_movements(user_id, product_id, created_at desc); create index sales_user_id_idx on public.sales(user_id, created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name, business_name, email) values (new.id, coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'), ''), 'MSM User'), coalesce(nullif(trim(new.raw_user_meta_data->>'business_name'), ''), 'My Business'), new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create trigger products_updated_at before update on public.products for each row execute procedure public.set_updated_at(); create trigger profiles_updated_at before update on public.profiles for each row execute procedure public.set_updated_at();
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.stock_movements enable row level security; alter table public.sales enable row level security;
create policy "profiles are private" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid()); create policy "products are private" on public.products for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "movements are private" on public.stock_movements for select using (user_id = auth.uid()); create policy "sales are private" on public.sales for select using (user_id = auth.uid());
create or replace function public.record_inventory_movement(p_product_id uuid, p_movement_type text, p_quantity integer, p_unit_price numeric default null, p_reference text default null, p_note text default null, p_customer text default null) returns void language plpgsql security definer set search_path = public as $$ declare current_stock integer; product_owner uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if p_movement_type not in ('IN','OUT') or p_quantity <= 0 then raise exception 'Invalid movement'; end if; select user_id into product_owner from public.products where id = p_product_id for update; if product_owner is null or product_owner <> auth.uid() then raise exception 'Product not found'; end if; select coalesce(sum(case when movement_type = 'IN' then quantity else -quantity end), 0) into current_stock from public.stock_movements where product_id = p_product_id; if p_movement_type = 'OUT' and p_quantity > current_stock then raise exception 'Insufficient stock'; end if; insert into public.stock_movements(user_id, product_id, movement_type, quantity, unit_price, reference, note) values (auth.uid(), p_product_id, p_movement_type, p_quantity, p_unit_price, nullif(trim(p_reference), ''), nullif(trim(p_note), '')); if p_movement_type = 'OUT' and p_unit_price is not null then insert into public.sales(user_id, product_id, quantity, unit_price, total, customer) values (auth.uid(), p_product_id, p_quantity, p_unit_price, p_quantity * p_unit_price, nullif(trim(p_customer), '')); end if; end; $$;
grant execute on function public.record_inventory_movement(uuid, text, integer, numeric, text, text, text) to authenticated;
